UPDATE agent_execution_policy_state SET status=#{status},revision=#{afterRevision},latest_decision_id=#{decisionRecordId},updated_at=#{now}
WHERE version_id=#{versionId} AND policy_id=#{policyId} AND project_id <=> #{projectId} AND content_sha256=#{contentHash}
 AND status=#{beforeStatus} AND revision=#{beforeRevision} AND schema_version='1.0.0' AND schema_manifest_sha256=#{schemaManifest}
 AND EXISTS(SELECT 1 FROM agent_execution_policy_decision d WHERE d.tenant_id=agent_execution_policy_state.tenant_id
  AND d.project_key=agent_execution_policy_state.project_key AND d.policy_id=agent_execution_policy_state.policy_id AND d.version_id=agent_execution_policy_state.version_id
  AND d.decision_record_id=#{decisionRecordId} AND d.before_revision=#{beforeRevision} AND d.after_revision=#{afterRevision} AND d.status=#{status} AND d.created_by=#{userId})
